	private static final String AL = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

	private static int[] decode( String s ){
		int[] out = new int[s.length() / 2];
		for (int i = 0; i < out.length; i++){
			char a = s.charAt( i * 2 ), b = s.charAt( i * 2 + 1 );
			out[i] = a == '-' ? -1 : AL.indexOf( a ) * 64 + AL.indexOf( b );
		}
		return out;
	}

	//한 번 풀어 둔 것을 계속 씀 (읽기 전용)
	private static int[] g, b, t, k;
	public static int[] ground(){ if (g == null) g = decode( GROUND ); return g; }
	public static int[] base(){ if (b == null) b = decode( BASE ); return b; }
	public static int[] top(){ if (t == null) t = decode( TOP ); return t; }
	public static int[] keys(){ if (k == null) k = decode( KEY ); return k; }
